import javax.tools.JavaCompiler;
import javax.tools.JavaFileObject;
import javax.tools.StandardJavaFileManager;
import javax.tools.ToolProvider;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/**
 * Stand-in for maven-compiler-plugin:compile. Compiles src/main/java into
 * the build output directory using the JDK compiler API, with the project's
 * resolved compile classpath. Annotation processors on the classpath
 * (Lombok) run automatically.
 */
public class CompilerMojo extends AbstractMojo {

    private MavenProject project;
    private File basedir;
    private File outputDirectory;
    private String release;

    @Override
    public void execute() throws MojoExecutionException {
        File sourceRoot = new File(basedir, "src/main/java");
        compile(project, sourceRoot, outputDirectory, release, "compile");
    }

    @SuppressWarnings("unchecked")
    static void compile(MavenProject project, File sourceRoot, File outputDirectory, String release, String scope)
            throws MojoExecutionException {
        if (!sourceRoot.isDirectory()) {
            return;
        }
        List<File> sources = new ArrayList<>();
        try (Stream<Path> walk = Files.walk(sourceRoot.toPath())) {
            walk.filter(p -> p.toString().endsWith(".java")).map(Path::toFile).forEach(sources::add);
        } catch (IOException e) {
            throw new MojoExecutionException("Failed to list source files", e);
        }
        if (sources.isEmpty()) {
            return;
        }
        if (!outputDirectory.isDirectory() && !outputDirectory.mkdirs()) {
            throw new MojoExecutionException("Could not create " + outputDirectory);
        }

        List<String> classpath;
        try {
            classpath = "test".equals(scope)
                    ? project.getTestClasspathElements()
                    : project.getCompileClasspathElements();
        } catch (Exception e) {
            throw new MojoExecutionException("Could not resolve " + scope + " classpath", e);
        }

        List<String> options = new ArrayList<>();
        options.add("-d");
        options.add(outputDirectory.getAbsolutePath());
        options.add("-encoding");
        options.add("UTF-8");
        options.add("-parameters");
        if (classpath != null && !classpath.isEmpty()) {
            options.add("-classpath");
            options.add(String.join(File.pathSeparator, classpath));
        }
        if (release != null && !release.isEmpty()) {
            options.add("--release");
            options.add(release);
        }

        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
        if (compiler == null) {
            throw new MojoExecutionException("No system Java compiler available (JDK required)");
        }
        try (StandardJavaFileManager fileManager = compiler.getStandardFileManager(null, null, null)) {
            Iterable<? extends JavaFileObject> units = fileManager.getJavaFileObjectsFromFiles(sources);
            JavaCompiler.CompilationTask task = compiler.getTask(null, fileManager, null, options, null, units);
            boolean ok = task.call();
            if (!ok) {
                throw new MojoExecutionException("Compilation failed");
            }
        } catch (IOException e) {
            throw new MojoExecutionException("Compilation I/O error", e);
        }
    }
}
